import React, { useEffect, useState } from "react";
import "./App.css";
import "./charts.css";
import Header from "./header";
import USAStates from "./usastates";

import Spinner from "react-bootstrap/Spinner";
import {
  LineChart,
  Bar,
  BarChart,
  PieChart,
  Area,
  AreaChart,
  ComposedChart,
  Line,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";

function Charts(props) {
  const [loading, setLoading] = useState(true);
  const [log, setLog] = useState(<YAxis />);

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [graphType, setGraphType] = useState("Line");
  const [test, setTest] = useState([]);

  var lastDate;
  var search = decodeURI(window.location.pathname.split("/").pop());

  useEffect(() => {
    let toFetch = `https://disease.sh/v3/covid-19/historical/${search}`;
    if (window.location.pathname.includes("state")) {
      let temp = search.toLowerCase();
      toFetch = `https://disease.sh/v3/covid-19/historical/usacounties/${temp}`;
    }

    if (window.location.pathname.includes("worldMap")) {
      const temp = search.toLowerCase();
      toFetch = `https://disease.sh/v3/covid-19/historical/${props.name}`;
    }

    const params = [];
    if (startDate) {
      params.push(`start=${startDate}`);
    }
    if (endDate) {
      params.push(`end=${endDate}`);
    }
    if (params.length > 0) {
      toFetch += `?${params.join("&")}`;
    }
    fetch(toFetch)
      .then((res) => res.json())
      .then((data) => {
        if (window.location.pathname.includes("state")) {
          const here = data;
          const filtered = here.filter((each) => {
            const a = props.name + "";
            const b = each.county + "";

            return a.toUpperCase() === b.toUpperCase();
          });
          setTest(filtered);
        } else {
          setTest(data);
        }
        setLoading(false);
      });

    // eslint-disable-next-line
  }, [startDate, endDate]);

  function normalizeDate(value) {
    if (!value) {
      return "";
    }

    const trimmed = value.trim();
    const normalized = trimmed.includes("/")
      ? trimmed
      : new Date(trimmed).toLocaleDateString("en-US");

    return normalized;
  }

  function testing(needed) {
    if (!test || (Array.isArray(test) && test.length === 0)) {
      return [];
    }

    let historyData = test.timeline;
    if (window.location.pathname.includes("state")) {
      historyData = test[0]?.timeline;
    }

    if (!historyData || !historyData.cases) {
      return [];
    }

    const dates = Object.keys(historyData.cases);
    const cases = Object.values(historyData.cases);
    const deaths = Object.values(historyData.deaths || {});
    const recovered = Object.values(historyData.recovered || {});

    const chartData = dates.map((date, index) => ({
      date: normalizeDate(date),
      confirmed: cases[index] || 0,
      deaths: deaths[index] || 0,
      recovered: window.location.pathname.includes("state")
        ? undefined
        : recovered[index] || 0,
    }));

    if (chartData.length > 0) {
      lastDate = chartData[chartData.length - 1].date;
    }

    return chartData;
  }

  function showFoot() {
    let fixed = (
      <div>
        <div className="graphMessage">Graph last updated on : {lastDate}</div>
      </div>
    );

    return fixed;
  }

  function returnLines(str) {
    var temp;
    function what() {
      if (graphType === "Line") {
        return Line;
      }

      if (graphType === "Bar") {
        return Bar;
      }

      if (graphType === "Area") {
        return Area;
      }

      if (graphType === "AreaLineComposed") {
        return;
      }
    }

    var TestGraph = what();

    temp = (
      <TestGraph
        dataKey={str}
        stroke={stringToColour(str)}
        fill={stringToColour(str)}
        dot={false}
      />
    );

    return temp;
  }

  var stringToColour = function (str) {
    if (str === "confirmed") {
      return "blue";
    }
    if (str === "deaths") {
      return "red";
    }
    if (str === "recovered") {
      return "green";
    }
  };

  function renderLineChart() {
    if (test.length === 0) {
      console.log("boloooooooooo");
    }
    var width;
    function what() {
      if (graphType === "Line") {
        return LineChart;
      }

      if (graphType === "Bar") {
        return BarChart;
      }
      if (graphType === "Area") {
        return AreaChart;
      }
      if (graphType === "Pie") {
        return PieChart;
      }
      if (graphType === "AreaLineComposed") {
        return ComposedChart;
      }
    }

    var TestGraph = what();

    if (test.message) {
      return <div>{test.message}</div>;
    }

    var current = testing("confirmed");
    var toShow;
    if (window.location.pathname.includes("state")) {
      toShow = props.name;
    }

    return (
      <div className="graphs">
        <br />
        <ResponsiveContainer width={width} height={400}>
          <TestGraph data={current}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="date" />
            {log}
            <Tooltip />
            <Legend />

            {returnLines("confirmed")}
            {returnLines("deaths")}
            {returnLines("recovered")}
          </TestGraph>
        </ResponsiveContainer>
        <div className="graphMessage">
          <h4>{toShow}</h4>
        </div>

        {showFoot()}
      </div>
    );
  }

  function changeStartDate(event) {
    setStartDate(event.target.value);
  }

  function changeEndDate(event) {
    setEndDate(event.target.value);
  }

  function isFrom() {
    if (!window.location.pathname.includes("state")) {
      return (
        <>
          <form onSubmit={(e) => e.preventDefault()}>
            <input
              type="date"
              value={startDate}
              onChange={changeStartDate}
              style={{ width: 140, marginRight: 8 }}
            />{" "}
            <input
              type="date"
              value={endDate}
              onChange={changeEndDate}
              style={{ width: 140 }}
            />{" "}
            {displayGraphMenu()}
          </form>
        </>
      );
    }

    return displayGraphMenu();
  }

  function displayGraphMenu() {
    function handleChange(e) {
      setGraphType(e.target.value);
    }

    var dropdown0 = (
      <>
        <select onChange={handleChange}>
          <option value={"Line"} checked>
            {" "}
            Graph type
          </option>
          <option value={"Line"}> Line</option>
          <option value={"Bar"}> Bar</option>
          <option value={"Area"}> Area</option>

          {/* <option value={"Composed"}> Composed</option> */}
        </select>
        <br />
      </>
    );

    return (
      <>
        {dropdown0}
        <select
          onChange={(e) => {
            if (e.target.value === "Linear") {
              setLog(<YAxis />);
            } else {
              setLog(
                <YAxis scale="log" domain={[0.01, "auto"]} allowDataOverflow />,
              );
            }
          }}
        >
          <option value={"Linear"}> Linear</option>
          <option value={"Log"}> Log</option>
        </select>
      </>
    );
  }

  return loading ? (
    <div className="spinners">
      {" "}
      <Spinner animation="grow" variant="primary" />
      <Spinner animation="grow" variant="secondary" />
      <Spinner animation="grow" variant="success" />
      <Spinner animation="grow" variant="danger" />
      <Spinner animation="grow" variant="warning" />
      <Spinner animation="grow" variant="info" />
    </div>
  ) : search === "USA" ? (
    <>
      <Header type="USA" />
      <USAStates />
      <div className="chartsNew">
        {isFrom()}
        {renderLineChart()}
      </div>
    </>
  ) : (
    <div className="chartsNew">
      <Header type={search} name={props.name} />

      {isFrom()}

      {renderLineChart()}
    </div>
  );
}

export default Charts;
