import React, { useEffect, useState } from "react";
import "./App.css";
import "./charts.css";
import Spinner from "react-bootstrap/Spinner";
import "./charts.css";
import Select from "react-select";

import {
  LineChart,
  Bar,
  BarChart,
  PieChart,
  Area,
  AreaChart,
  ComposedChart,
  Line,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";

function Charts(props) {
  const [loading, setLoading] = useState(true);
  const [currentType, setCurrenType] = useState("confirmed");
  const [showAll, setShowAll] = useState(false);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [log, setLog] = useState(<YAxis />);

  const [countryList, setCountryList] = useState(["USA"]);
  const [availableCountries, setAvailableCountries] = useState([]);
  const [selectedCountries, setSelectedCountries] = useState([
    { label: "USA", value: "USA" },
  ]);

  const [test, setTest] = useState([]);
  const [graphType, setGraphType] = useState("Line");

  // Fetch list of all available countries on component mount
  useEffect(() => {
    const fetchCountries = async () => {
      try {
        const res = await fetch("https://disease.sh/v3/covid-19/countries", {
          headers: { Accept: "application/json" },
        });
        const data = await res.json();
        // disease.sh returns an array of country objects with "country" property
        const countries = data.map((item) => item.country).sort();
        setAvailableCountries(countries);
      } catch (e) {
        console.error("Error fetching countries:", e);
        // Fallback to some common countries if API fails
        setAvailableCountries([
          "USA",
          "India",
          "Brazil",
          "Russia",
          "France",
          "UK",
          "Italy",
          "Spain",
          "Germany",
          "Canada",
          "Japan",
          "Mexico",
          "China",
          "South Korea",
        ]);
      }
    };
    fetchCountries();
  }, []);

  // Fetch historical data from disease.sh
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      let countries = props.from === "small" ? [props.name] : countryList;
      let results = [];

      for (let country of countries) {
        try {
          let url = `https://disease.sh/v3/covid-19/historical/${country}`;
          const params = [];

          if (startDate) {
            params.push(`start=${startDate}`);
          }
          if (endDate) {
            params.push(`end=${endDate}`);
          }
          if (params.length > 0) {
            url += `?${params.join("&")}`;
          }

          const res = await fetch(url, {
            headers: { Accept: "application/json" },
          });
          const data = await res.json();
          if (data && data.timeline) {
            results.push({ ...data, country });
          }
        } catch (e) {
          console.error("API error for country", country, ":", e);
        }
      }
      setTest(results);
      setLoading(false);
      if (props.from === "small") {
        setCountryList([props.name]);
      }
    };
    fetchData();
    // eslint-disable-next-line
  }, [countryList, startDate, endDate]);

  function normalizeDate(value) {
    if (!value) {
      return "";
    }

    const trimmed = value.trim();
    if (!trimmed.includes("/")) {
      return new Date(trimmed).toLocaleDateString("en-US");
    }

    return trimmed;
  }

  // disease.sh provides historical data with timeline
  // Transform into format suitable for recharts
  function testing(needed) {
    if (!Array.isArray(test) || test.length === 0) {
      return [];
    }

    const countries = countryList.filter((country) =>
      test.some((element) => element.country === country),
    );

    const casesArray = [];
    const deathsArray = [];
    const recoveredArray = [];

    countries.forEach((country) => {
      const element = test.find((item) => item.country === country);
      if (!element || !element.timeline) {
        return;
      }

      const historyData = element.timeline;
      const dates = Object.keys(historyData.cases || {});
      const cases = Object.values(historyData.cases || {});
      const deaths = Object.values(historyData.deaths || {});
      const recovered = Object.values(historyData.recovered || {});

      dates.forEach((date, index) => {
        const label = normalizeDate(date);
        const casesEntry = casesArray.find((entry) => entry.date === label);
        const deathsEntry = deathsArray.find((entry) => entry.date === label);
        const recoveredEntry = recoveredArray.find(
          (entry) => entry.date === label,
        );

        if (!casesEntry) {
          casesArray.push({ date: label });
        }
        if (!deathsEntry) {
          deathsArray.push({ date: label });
        }
        if (!recoveredEntry) {
          recoveredArray.push({ date: label });
        }

        const casesRow = casesArray.find((entry) => entry.date === label);
        const deathsRow = deathsArray.find((entry) => entry.date === label);
        const recoveredRow = recoveredArray.find(
          (entry) => entry.date === label,
        );

        casesRow[country] = cases[index] || 0;
        deathsRow[country] = deaths[index] || 0;
        recoveredRow[country] = recovered[index] || 0;
      });
    });

    if (currentType === "confirmed" && needed === "confirmed") {
      return casesArray;
    }

    if (currentType === "recovered" || needed === "recovered") {
      return recoveredArray;
    }
    if (currentType === "deaths" || needed === "deaths") {
      return deathsArray;
    }
  }

  function showFoot() {
    // disease.sh provides the updated timestamp
    let fixed = (
      <span className="graphMessage">
        Graph last updated: Today (disease.sh)
      </span>
    );
    return fixed;
  }

  function returnLines() {
    var temp;
    function what() {
      if (graphType === "Line") {
        return Line;
      }

      if (graphType === "Bar") {
        return Bar;
      }

      if (graphType === "Area") {
        return Area;
      }

      if (graphType === "AreaLineComposed") {
        return;
      }
    }

    var TestGraph = what();
    if (countryList.length === 1) {
      temp = (
        <TestGraph
          dataKey={countryList[0]}
          stroke={stringToColour(countryList[0])}
          fill={stringToColour(countryList[0])}
          dot={false}
        />
      );
    }
    if (countryList.length > 1) {
      temp = countryList.map((each) => {
        return (
          <TestGraph
            key={each}
            dataKey={each}
            stroke={stringToColour(each)}
            fill={stringToColour(each)}
            dot={false}
          />
        );
      });
    }

    return temp;
  }

  var stringToColour = function (str) {
    var hash = 0;
    for (var i = 0; i < str.length; i++) {
      hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    var colour = "#";
    for (var j = 0; j < 3; j++) {
      var value = (hash >> (j * 8)) & 0xff;
      colour += ("00" + value.toString(16)).substr(-2);
    }
    return colour;
  };

  function renderLineChart() {
    var width;
    function what() {
      if (graphType === "Line") {
        return LineChart;
      }

      if (graphType === "Bar") {
        return BarChart;
      }
      if (graphType === "Area") {
        return AreaChart;
      }
      if (graphType === "Pie") {
        return PieChart;
      }
      if (graphType === "AreaLineComposed") {
        return ComposedChart;
      }
    }

    var TestGraph = what();
    if (props.from === "small") {
      width = "120%";
    }

    if (!showAll) {
      var current = testing("confirmed");

      var toShow = currentType.charAt(0).toUpperCase() + currentType.slice(1);

      return (
        <div className="graphs">
          <div>
            {" "}
            <h3>{toShow} </h3>
            <ResponsiveContainer width={width} height={400}>
              <TestGraph data={current}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="date" />
                {log}
                <Tooltip />
                <Legend />

                {returnLines()}
              </TestGraph>
            </ResponsiveContainer>
            {showFoot()}
          </div>
        </div>
      );
    }

    return (
      <div className="graphs">
        <div>
          {" "}
          <h3>Confirmed </h3>
          <ResponsiveContainer width="95%" height={400}>
            <TestGraph data={testing("confirmed")} syncId="anyId">
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />
              syncId="anyId"
              {returnLines()}
            </TestGraph>
          </ResponsiveContainer>
        </div>
        <div>
          {" "}
          <h3>Recovered </h3>
          <ResponsiveContainer width="95%" height={400}>
            <TestGraph data={testing("recovered")} syncId="anyId">
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />

              {returnLines()}
            </TestGraph>
          </ResponsiveContainer>
        </div>
        <div>
          {" "}
          <h3>Deaths </h3>
          <ResponsiveContainer width="95%" height={400}>
            <TestGraph data={testing("deaths")} syncId="anyId">
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />

              {returnLines()}
            </TestGraph>
          </ResponsiveContainer>
        </div>

        {showFoot()}
      </div>
    );
  }

  function changeStartDate(event) {
    setStartDate(event.target.value);
  }

  function changeEndDate(event) {
    setEndDate(event.target.value);
  }

  function handleTypes() {
    return (
      <>
        <form
          onSubmit={(e) => {
            e.preventDefault();
          }}
        >
          <select onChange={handleType}>
            <option value="confirmed"> Confirmed</option>
            <option value="recovered"> Recovered</option>
            <option value="deaths"> Deaths</option>
            <option value="all"> All</option>
          </select>{" "}
          <input
            type="date"
            value={startDate}
            onChange={changeStartDate}
            style={{ width: 140, marginRight: 8 }}
          />{" "}
          <input
            type="date"
            value={endDate}
            onChange={changeEndDate}
            style={{ width: 140 }}
          />{" "}
          {dropdown0}
        </form>
      </>
    );
  }

  function returnCountryList() {
    // Use the available countries fetched from disease.sh
    // Fallback to test data if available
    if (availableCountries.length > 0) {
      return availableCountries;
    }
    // Fallback: get from test data if API hasn't fetched country list yet
    var full = Object.values(test);
    let again = new Set();
    full.map((ele, i) => {
      return again.add(ele.country);
    });
    return Array.from(again);
  }

  function handleList(opt) {
    const nextCountries = (opt || []).map((each) => each.value);
    setSelectedCountries(opt || []);
    setCountryList(nextCountries);
  }

  function handleType(e) {
    if (e.target.value === "all") {
      setShowAll(true);
    } else {
      setShowAll(false);
      setCurrenType(e.target.value);
    }
  }

  function isFrom() {
    return (
      <>
        <br />
        Select countries to add to the graph:
        <div>
          <Select
            isMulti
            closeMenuOnSelect={false}
            value={selectedCountries}
            onChange={(opt) => {
              handleList(opt);
            }}
            options={returnCountryList().map((value, i) => ({
              label: value,
              key: i,
              value: value,
            }))}
          />
        </div>
        {handleTypes()}
      </>
    );
  }

  function handleChange(e) {
    setGraphType(e.target.value);
  }

  var dropdown0 = (
    <>
      <select onChange={handleChange}>
        <option defaultChecked disabled>
          {" "}
          Graph type
        </option>
        <option value={"Line"}> Line graph</option>
        <option value={"Bar"}> Bar graph</option>
        <option value={"Area"}> Area graph</option>

        {/* <option value={"Composed"}> Composed</option> */}
      </select>
      <select
        onChange={(e) => {
          if (e.target.value === "Linear") {
            setLog(<YAxis />);
          } else {
            setLog(
              <YAxis scale="log" domain={[0.01, "auto"]} allowDataOverflow />,
            );
          }
        }}
      >
        <option value={"Linear"}> Linear</option>
        <option value={"Log"}> Log</option>
      </select>{" "}
    </>
  );

  return loading ? (
    <div className="spinners">
      <Spinner animation="grow" variant="primary" />
      <Spinner animation="grow" variant="secondary" />
      <Spinner animation="grow" variant="success" />
      <Spinner animation="grow" variant="danger" />
      <Spinner animation="grow" variant="warning" />
      <Spinner animation="grow" variant="info" />
    </div>
  ) : (
    <div className="chartsNew">
      {isFrom()}
      {renderLineChart()}
    </div>
  );
}

export default Charts;
